// ---------------------------------------------------------------- rendering
const gT=p=>Array.isArray(p)?t(p[0],p[1]):p;
function guideHTML(g){return GSECT.filter(([k])=>g[k]&&g[k].length).map(([k,de,en])=>{
    const items=g[k].map(x=>`<li>${esc(gT(x))}</li>`).join('');
    return `<div class="gsec"><b>${esc(t(de,en))}</b>${k==='setup'?`<ol>${items}</ol>`:g[k].length>1?`<ul>${items}</ul>`:`<p>${esc(gT(g[k][0]))}</p>`}</div>`}).join('')}
function guideBox(g,open,plain){const d=document.createElement('details');d.className='guide';d.dataset.guide=g.id;d.open=!!open;
  d.innerHTML=`<summary>${plain?'':esc(t('Anleitung','Guide'))+': '}${esc(gT(g.t))}</summary><div class="gbody">${guideHTML(g)}</div>`;return d}
// Funktionen: rows sorted into the groups, each feature one short line (name, mark, switch).
// A tap on the name opens its sentence, marks, guide and settings below; switching it on opens it too.
function guidesFeat(){const pane=$('pane-feat');if(!pane||pane.dataset.grouped)return;pane.dataset.grouped='1';
  GGROUPS.forEach(([gid,de,en])=>{const rows=GUIDES.filter(g=>g.grp===gid&&g.sw).map(g=>{const el=$(g.sw);return el&&pane.contains(el)?[g,el.closest('.setrow')]:null}).filter(Boolean);
    if(!rows.length)return;
    const box=document.createElement('details');box.className='fgrp';box.open=true;box.dataset.grp=gid;
    box.innerHTML=`<summary><b>${esc(t(de,en))}</b><span class="fcount"></span></summary>`;
    const bar=pane.querySelector(':scope>.savebar');bar?pane.insertBefore(box,bar):pane.appendChild(box);
    // each switch takes its settings along: every block on the page with data-show="<its id>" goes right
    // below it (indented there, only shown while the switch is on), wherever it stands in the HTML
    // a switch that only shows while another one is on (Pakete under E-Mail) comes along with that one
    const take=(sw,to)=>pane.querySelectorAll(`:scope>[data-show="${sw}"]`).forEach(d=>{
      if(!d.classList.contains('setrow')){d.classList.add('fdetail');to.appendChild(d);return}
      to.appendChild(d);const inner=d.querySelector('.tgl input[id]');if(inner)take(inner.id,to)});
    rows.forEach(([g,row])=>{featTags(g,row);if(row.parentNode===box||row.closest('.fitem')||(row.dataset.show&&rows.some(([x])=>x.sw===row.dataset.show)))return;
      const it=document.createElement('div');it.className='fitem';it.dataset.sw=g.sw;box.appendChild(it);it.appendChild(row);take(g.sw,it);featItem(it,row)})});
  featBar(pane);guidesCount();grundLoad()}
function featItem(it,row){const btn=document.createElement('button');btn.type='button';btn.className='fexp';btn.setAttribute('aria-expanded','false');
  btn.setAttribute('aria-label',t('Details','Details'));row.prepend(btn);
  const nm=row.querySelector('.lbl>b');if(nm){const n=document.createElement('span');n.className='fneed';n.hidden=true;n.textContent=t('braucht dich','needs you');nm.appendChild(n)}
  btn.onclick=()=>featOpen(it,!it.classList.contains('open'));
  row.querySelector('.lbl').addEventListener('click',e=>{if(e.target.closest('button,a,input,select,textarea'))return;featOpen(it,!it.classList.contains('open'))});
  const sw=$(it.dataset.sw);if(sw)sw.addEventListener('change',()=>{if(sw.checked)featOpen(it,true)})}
function featOpen(it,on){it.classList.toggle('open',on);const b=it.querySelector('.fexp');if(b)b.setAttribute('aria-expanded',on?'true':'false');if(window.featSide)featSide(it,on)}
// an item needs you while its switch is on and a field it needs is empty ([data-req]) or a state says so ([data-need="1"])
// (fdetail.js: while the item shows on the right, its rows sit there)
const featNeed=it=>{const sw=$(it.dataset.sw),q=sel=>[...it.querySelectorAll(sel),...(it.classList.contains('fside')&&$('fdet')?$('fdet').querySelectorAll(sel):[])];
  return !!(sw&&sw.checked&&(q('[data-req]').some(x=>!x.value.trim())||q('[data-need="1"]').length))};
const FFILT=[['all','Alle','All'],['on','An','On'],['off','Aus','Off'],['rec','Empfohlen','Recommended'],['need','Braucht dich','Needs you']];
let featF='all';try{featF=localStorage.getItem('featfilter')||'all'}catch(e){}
function featBar(pane){const top=document.createElement('div');top.className='fbar';
  top.innerHTML=`<div class="ffilt" role="group">${FFILT.map(([k,de,en])=>`<button type="button" data-f="${k}"><span>${esc(t(de,en))}</span> <i></i></button>`).join('')}</div>`+
    `<div class="fjump">${[...pane.querySelectorAll('.fgrp')].map(b=>`<button type="button" data-g="${b.dataset.grp}">${esc(b.querySelector('summary b').textContent)}</button>`).join('')}</div>`;
  const first=pane.querySelector('.fgrp');pane.insertBefore(top,first);
  top.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>{featF=b.dataset.f;try{localStorage.setItem('featfilter',featF)}catch(e){}guidesCount()});
  top.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{const g=pane.querySelector(`.fgrp[data-grp="${b.dataset.g}"]`);if(!g)return;
    if(g.hidden){featF='all';guidesCount()}g.open=true;g.scrollIntoView({block:'start',behavior:'smooth'})})}
// Grundausstattung (features.GRUNDAUSSTATTUNG, Dominik 2026-10-17): a card above the list while some of it is off or
// the internet question is open, „Empfohlen“ behind its names and as a filter. The lists come from the panel only.
let GRUND=null;
// admins only (start.js calls it again once whoami named the admin): before, every profile asked at the page start, got 401
// and the admin sign-in window covered the page
async function grundLoad(){if(!ADMIN)return;try{GRUND=await (await api('/api/admin/grundausstattung')).json()}catch{GRUND=null}grundDraw()}
function grundDraw(done){const pane=$('pane-feat');if(!pane)return;const g=GRUND,rec=new Set(g?g.basis.keys:[]);
  pane.querySelectorAll('.fitem').forEach(it=>{const b=it.querySelector('.setrow .lbl>b');if(!b)return;let m=b.querySelector('.frec');
    if(!rec.has(it.dataset.sw)){if(m)m.remove();return}
    if(!m){m=document.createElement('span');m.className='frec';m.textContent=t('Empfohlen','Recommended');b.appendChild(m)}});
  guidesCount();let card=$('grundcard');
  const off=g?g.basis.keys.filter(k=>!g.basis.on.includes(k)):[],ask=!!(g&&g.internet.frage==='offen');
  if(!g||(!off.length&&!ask&&!done)){if(card)card.remove();return}
  if(!card){card=document.createElement('div');card.id='grundcard';card.className='grundcard';pane.insertBefore(card,pane.querySelector('.fbar')||pane.querySelector('.fgrp'))}
  const nm=k=>esc(t(...((g.names||{})[k]||[k,k]))),n=g.basis.keys.length;let h='';
  // V01.0.788: one line with „Alle übernehmen“; what is still off opens below it (Funktionen stays short)
  if(off.length)h+=`<div class="gcpart"><div class="gcline"><b>${esc(t('Grundausstattung für ein gutes Gespräch','Basic set for a good conversation'))}</b> <span class="gcn">${esc(t(`${n-off.length} von ${n} an`,`${n-off.length} of ${n} on`))}</span>`+
    `<button class="b p" type="button" data-grund="basis">${esc(t('Alle übernehmen','Take them all'))}</button><button class="b" type="button" data-grund="mehr" aria-expanded="false">${esc(t('Was fehlt?','What is off?'))}</button></div>`+
    `<div class="gcmore" hidden><div class="fh">${esc(t('Geht ohne Einrichtung, bleibt im Spark und braucht kein Zusatzmodell. Gäste bekommen davon nichts. Noch aus:','Needs no setup, stays in the Spark and loads no extra model. Guests get none of it. Still off:'))}</div>`+
    `<div class="ftags">${off.map(k=>`<span class="ftag">${nm(k)}</span>`).join('')}</div>`+
    `<div class="row"><button class="b" type="button" data-grund="zeigen">${esc(t('Einzeln ansehen','Look at each'))}</button></div></div></div>`;
  if(ask)h+=`<div class="gcpart"><b>${esc(t('Darf der Spark ins Internet?','May the Spark use the internet?'))}</b>`+
    `<div class="fh">${esc(t('Ja schaltet ein: ','Yes switches on: ')+g.internet.keys.filter(k=>k!=='chat.search'||g.internet.search_url).map(k=>t(...((g.names||{})[k]||[k,k]))).join(', ')+'. '+
      t('Hinaus gehen nur dein Ort fürs Wetter, Suchwörter und zwei feste Adressen, mit denen der Dienst-Wächter das Internet prüft; nie Mails oder Dokumente.','Only your place for the weather, search words and two fixed addresses the service watch checks the internet with go out; never mails or documents.')+
      (g.internet.search_url?'':' '+t('Die Websuche kommt dazu, sobald unter Funktionen → Websuche eine SearXNG-Adresse steht.','The web search joins once Funktionen → Websuche has a SearXNG address.')))}</div>`+
    `<div class="row"><button class="b" type="button" data-grund="ja">${esc(t('Ja','Yes'))}</button><button class="b" type="button" data-grund="nein">${esc(t('Nein, nur im Heimnetz','No, home network only'))}</button></div></div>`;
  card.innerHTML=h+`<div class="fh gcmsg" role="status">${done?esc(done):''}</div>`;
  card.querySelectorAll('[data-grund]').forEach(b=>b.onclick=()=>grundTake(b.dataset.grund,b))}
async function grundTake(w,btn){
  if(w==='mehr'){const m=btn.closest('.gcpart').querySelector('.gcmore');m.hidden=!m.hidden;btn.setAttribute('aria-expanded',String(!m.hidden));return}
  if(w==='zeigen'){featF='rec';try{localStorage.setItem('featfilter',featF)}catch(e){}guidesCount();const bar=$('pane-feat').querySelector('.fbar');if(bar)bar.scrollIntoView({block:'start',behavior:'smooth'});return}
  btn.disabled=true;
  try{const r=await (await api('/api/admin/grundausstattung',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(w==='basis'?{teil:'basis',on:true}:{teil:'internet',on:w==='ja'})})).json();
    // the form and its copy of the settings take the new values, so a later save keeps them (no reload: other edits stay)
    (r.turned||[]).forEach(k=>{const el=$(k),[s,x]=k.split('.');if(el)el.checked=true;if(typeof CFG!=='undefined'&&CFG&&CFG[s])CFG[s][x]=true});
    if(typeof CFG!=='undefined'&&CFG&&CFG.chat)CFG.chat.grund_internet=r.internet.frage;
    GRUND=r;if(typeof cfgDeps==='function')cfgDeps();
    grundDraw(w==='nein'?t('Gemerkt: der Spark bleibt im Heimnetz.','Noted: the Spark stays in the home network.'):
      t(`${(r.turned||[]).length} eingeschaltet. Zurücknehmen unter Zustand → Logs → Admin-Protokoll.`,`${(r.turned||[]).length} switched on. Take it back under Zustand → Logs → Admin-Protokoll.`))}
  catch(e){btn.disabled=false;const m=$('grundcard')&&$('grundcard').querySelector('.gcmsg');if(m)m.textContent=e.message}}
// a search hit inside a closed or filtered-out item: show and open it
function featShow(el){const it=el&&el.closest&&(el.closest('#pane-feat .fitem')||(el.closest('#fdet')&&window.featCur&&featCur()));if(!it)return;if(it.hidden){featF='all';guidesCount()}featOpen(it,true)}
function guidesCount(){const pane=$('pane-feat');if(!pane)return;const items=[...pane.querySelectorAll('.fitem')];
  const st=items.map(it=>{const sw=$(it.dataset.sw),on=!!(sw&&sw.checked),need=featNeed(it);it.querySelector('.fneed').hidden=!need;return {it,on,need}});
  const rec=x=>!!(GRUND&&GRUND.basis.keys.includes(x.it.dataset.sw));
  const n={all:st.length,on:st.filter(x=>x.on).length,off:st.filter(x=>!x.on).length,rec:st.filter(rec).length,need:st.filter(x=>x.need).length};
  if((featF==='need'&&!n.need)||(featF==='rec'&&!n.rec))featF='all';
  pane.querySelectorAll('.ffilt [data-f]').forEach(b=>{const k=b.dataset.f;b.querySelector('i').textContent=n[k];b.classList.toggle('on',k===featF);b.hidden=(k==='need'||k==='rec')&&!n[k];b.classList.toggle('need',k==='need')});
  st.forEach(x=>{x.it.hidden=featF==='on'?!x.on:featF==='off'?x.on:featF==='rec'?!rec(x):featF==='need'?!x.need:false});
  // a group counts its function rows like the filters above, not every sub-switch (code check 19.10. D3)
  pane.querySelectorAll('.fgrp').forEach(b=>{const s=st.filter(x=>b.contains(x.it)),on=s.filter(x=>x.on).length;
    b.hidden=!s.some(x=>!x.it.hidden);
    const j=pane.querySelector(`.fjump [data-g="${b.dataset.grp}"]`);if(j)j.hidden=b.hidden;
    b.querySelector('.fcount').textContent=t(`${on} von ${s.length} an`,`${on} of ${s.length} on`)})}
document.addEventListener('change',e=>{if(e.target.closest&&e.target.closest('#pane-feat'))guidesCount()});
document.addEventListener('input',e=>{if(e.target.closest&&e.target.closest('#pane-feat [data-req]'))guidesCount()});
// small marks behind a feature's name instead of repeating it in every description
const ME_NAME={kannbox:['Was ich kann','What I can do'],teilbox:['Geteilt','Shared'],bgbox:['Mein Zustand','My status'],setbox:['Gespräch','Conversation'],notebox:['Mitteilungen','Notifications'],factbox:['Gedächtnis','Memory'],wissbox:['Was ich über dich weiß','What I know about you'],voicebox:['Sprechererkennung','Speaker identification'],roombox:['Raum-Modus','Room mode'],
  probox:['Von selbst','By itself'],agentbox:['Aufträge','Jobs'],wxbox:['Wetter','Weather'],trbox:['Bus und Bahn','Bus and train'],feedbox:['Reddit und Feeds','Reddit and feeds'],
  writebox:['Schreibhilfe','Writing help'],deskbox:['Begleiter','Companion'],docbox:['Dokumente','Documents'],bildbox:['Bilder','Pictures'],musikbox:['Musik','Music'],rmbox:['reMarkable','reMarkable'],habox:['Smart Home','Smart home'],tgbox:['Telegram','Telegram'],appbox:['iPhone-App','iPhone app'],andbox:['Android-App','Android app'],pebbox:['Pebble-Uhr','Pebble watch'],termbox:['Terminal','Terminal'],mcpbox:['Spark als MCP-Server','Spark as MCP server'],mymcpbox:['Meine MCP-Dienste','My MCP services'],storebox:['Speicher','Storage'],espbox:['Lautsprecher','Speakers'],secbox:['Sicherheit','Security'],usebox:['Verbrauch','Usage'],telbox:['Telefon','Phone']};
function featTags(g,row){const lbl=row.querySelector('.lbl');if(!lbl||lbl.querySelector('.ftags'))return;const tags=[];
  const me=g.me||g.mep;   // mep: the profile switch sits on that page, without the guide being shown there
  if(me&&ME_NAME[me])tags.push(['me',t('einrichten unter Ich → ','set up under Me → ')+t(...ME_NAME[me])]);
  else if(me&&typeof OWN_PAGES!=='undefined'&&OWN_PAGES[me])tags.push(['me',t('einrichten unter ','set up under ')+OWN_PAGES[me][1]+t(' → Einstellungen',' → Settings')]);
  if(g.ng)tags.push(['ng',t('nie für Gäste','never for guests')]);
  if(g.ro)tags.push(['ro',t('nur lesen','read only')]);
  if(g.out&&g.out!==NOTHING_OUT)tags.push(['out',t('verlässt das Haus','leaves the house')]);
  if(!tags.length)return;const d=document.createElement('div');d.className='ftags';
  d.innerHTML=tags.map(([k,x])=>`<span class="ftag ${k}">${esc(x)}</span>`).join('');lbl.querySelector('span').after(d)}
// A small "Anleitung" button next to every admin switch that has a guide; it opens the guide below the row.
function guidesSwitches(){GUIDES.filter(g=>g.sw).forEach(g=>{const el=$(g.sw);if(!el||document.querySelector(`[data-gbtn="${g.id}"]`))return;
  const row=el.closest('.setrow'),anchor=row||(el.closest('label.chk')||el),after=row||(anchor.nextElementSibling&&anchor.nextElementSibling.classList.contains('fh')?anchor.nextElementSibling:anchor);
  const btn=document.createElement('button');btn.type='button';btn.className='gbtn';btn.dataset.gbtn=g.id;btn.textContent=t('Anleitung','Guide');
  // the text is written at the first tap: some 70 guides at every page start were most of guides.js' time (V01.0.750)
  const box=document.createElement('div');box.className='guide inline';box.hidden=true;
  btn.onclick=()=>{if(!box.firstChild)box.innerHTML=`<div class="gbody">${guideHTML(g)}</div>`;box.hidden=!box.hidden;btn.classList.toggle('on',!box.hidden)};
  (row?row.querySelector('.lbl'):after).appendChild(btn);after.after(box)})}
// "Ich" window: the guides of a page at its top (re-added when a page redraws itself).
function guidesMe(id){const page=$(id);if(!page)return;const list=GUIDES.filter(g=>g.me===id);
  list.slice().reverse().forEach(g=>{if(!page.querySelector(`details.guide[data-guide="${g.id}"]`))page.prepend(guideBox(g,false))})}
// Group of an "Ich" page, for the headers in its menu.
const meGroup=id=>{const g=GUIDES.find(x=>x.me===id&&x.id!=='hands');return g?g.grp:null};
// Funktionen → Anleitungen: all guides, grouped.
function guidesAll(){const el=$('guidelist');if(!el||el.firstChild)return;
  el.innerHTML=GGROUPS.map(([gid,de,en])=>`<div class="ggrp"><h3>${esc(t(de,en))}</h3><div data-g="${gid}"></div></div>`).join('');
  GUIDES.forEach(g=>el.querySelector(`[data-g="${g.grp}"]`).appendChild(guideBox(g,false,true)))}
// the list of all guides is drawn when its page (Funktionen → Anleitungen) opens, not at every page start
function guidesInit(){guidesFeat();guidesSwitches();const sec=$('int');if(!sec)return;if(sec.classList.contains('on'))guidesAll();
  new MutationObserver(()=>{if(sec.classList.contains('on'))guidesAll()}).observe(sec,{attributes:true,attributeFilter:['class']})}
guidesInit();
